class Solution {public:
 int countPartitions(vector<int>& nums,int k){
  const int MOD=1000000007;int n=nums.size(),l=0;deque<int> mn,mx;
  vector<long long> dp(n+1),pref(n+2);dp[0]=1;pref[1]=1;
  for(int r=0;r<n;++r){
   while(!mn.empty()&&nums[mn.back()]>=nums[r])mn.pop_back();mn.push_back(r);
   while(!mx.empty()&&nums[mx.back()]<=nums[r])mx.pop_back();mx.push_back(r);
   while(nums[mx.front()]-nums[mn.front()]>k){if(mn.front()==l)mn.pop_front();if(mx.front()==l)mx.pop_front();++l;}
   dp[r+1]=(pref[r+1]-pref[l]+MOD)%MOD;pref[r+2]=(pref[r+1]+dp[r+1])%MOD;
  }return dp[n];
 }
};
